import"./chunk-VC46IEJQ.js";var t=([a,o])=>({en:a,zh:o}),e=(a,o,s,n,i,h,l,d,r)=>({name:t(a),desc:t(o),tour:t(s),...r?{spoiler:t(r)}:{},source:{confidence:n,refs:i,book:t(h),unknown:t(l),interpretation:t(d)}}),c={id:"lannisport",intro:{en:"Lannisport is the rich port city beneath Casterly Rock, the greatest harbour of the west. The novels name it far more often than they describe it, so its stone, roofs and gilded lions here are a reconstruction.",zh:"\u5170\u5C3C\u65AF\u6E2F\u662F\u51EF\u5CA9\u57CE\u811A\u4E0B\u7684\u5BCC\u5EB6\u6E2F\u57CE\uFF0C\u897F\u5883\u7B2C\u4E00\u5927\u6E2F\u3002\u5C0F\u8BF4\u63D0\u5230\u5B83\u7684\u6B21\u6570\u8FDC\u591A\u4E8E\u63CF\u5199\u5B83\u7684\u7B14\u58A8\uFF0C\u56E0\u6B64\u573A\u666F\u4E2D\u7684\u77F3\u5899\u3001\u5C4B\u74E6\u4E0E\u9540\u91D1\u72EE\u50CF\u7686\u5C5E\u91CD\u6784\u3002"},notes:{en:"From the books and The World of Ice & Fire: a large, wealthy port city at the foot of Casterly Rock with a great harbour, home to a cadet branch, the Lannisters of Lannisport; the ironborn burned the Lannister fleet here at the start of Greyjoy's Rebellion. Wiki-level only (low confidence): gates guarded by stone lions, a lighthouse, a domed sept, a cadet palace. Invented: street grid, building shapes, breakwaters, market and all colours. The Rock in the distance is a simplified stand-in.",zh:"\u5C0F\u8BF4\u4E0E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u786E\u7ACB\uFF1A\u51EF\u5CA9\u57CE\u811A\u4E0B\u89C4\u6A21\u5B8F\u5927\u3001\u5BCC\u5EB6\u7E41\u8363\u7684\u6E2F\u57CE\uFF0C\u62E5\u6709\u5927\u6E2F\uFF0C\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7684\u65C1\u652F\u201C\u5170\u5C3C\u65AF\u6E2F\u7684\u5170\u5C3C\u65AF\u7279\u201D\u5C45\u4E8E\u6B64\u5730\uFF1B\u845B\u96F7\u4E54\u4F0A\u53DB\u4E71\u4E4B\u521D\uFF0C\u94C1\u6C11\u66FE\u5728\u6B64\u711A\u6BC1\u5170\u5C3C\u65AF\u7279\u8230\u961F\u3002\u4EC5\u89C1\u4E8E\u7EF4\u57FA\u5C42\u9762\uFF08\u53EF\u4FE1\u5EA6\u4F4E\uFF09\uFF1A\u77F3\u72EE\u5B88\u536B\u7684\u57CE\u95E8\u3001\u706F\u5854\u3001\u7A79\u9876\u5723\u5802\u4E0E\u65C1\u652F\u5B85\u90B8\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u8857\u9053\u7F51\u683C\u3001\u5EFA\u7B51\u9020\u578B\u3001\u9632\u6CE2\u5824\u3001\u96C6\u5E02\u4E0E\u5168\u90E8\u8272\u5F69\u3002\u8FDC\u5904\u7684\u51EF\u5CA9\u57CE\u4E3A\u7B80\u5316\u793A\u610F\u3002"},tour:["harbor","lighthouse","breakwaters","lannister-fleet","warehouses","market-square","lion-street","great-sept","cadet-palace","lion-gates","city-walls","casterly-rock-view"],sources:[{ref:"agot",checked:"memory",note:{en:"Lannisport is mentioned throughout as the great port beneath the Rock (and in backstory, the tourney after Greyjoy's Rebellion); physical description is scant. Recalled, not re-read.",zh:"\u5170\u5C3C\u65AF\u6E2F\u4F5C\u4E3A\u5DE8\u5CA9\u4E0B\u7684\u5927\u6E2F\u8D2F\u7A7F\u5168\u4E66\uFF08\u524D\u53F2\u4E2D\u8FD8\u6709\u845B\u96F7\u4E54\u4F0A\u53DB\u4E71\u540E\u5728\u6B64\u4E3E\u884C\u7684\u6BD4\u6B66\u5927\u4F1A\uFF09\uFF0C\u4F46\u5B9E\u4F53\u63CF\u5199\u5F88\u5C11\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"acok",checked:"memory",note:{en:"Theon recalls the ironborn burning the Lannister fleet at Lannisport when the rebellion began. Recalled.",zh:"\u5E2D\u6069\u56DE\u5FC6\u8D77\u53DB\u4E71\u4E4B\u521D\uFF0C\u94C1\u6C11\u5728\u5170\u5C3C\u65AF\u6E2F\u711A\u6BC1\u5170\u5C3C\u65AF\u7279\u8230\u961F\u3002\u51ED\u8BB0\u5FC6\u3002"}},{ref:"twoiaf",checked:"not-accessed",note:{en:"The companion book's text on Lannisport was not consulted.",zh:"\u672A\u67E5\u9605\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u4E2D\u5173\u4E8E\u5170\u5C3C\u65AF\u6E2F\u7684\u6587\u5B57\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Lion-guarded gates, a lighthouse, a domed sept and a cadet palace come from a web-search summary of wiki-style pages; neither fetched nor matched to the novels.",zh:"\u77F3\u72EE\u57CE\u95E8\u3001\u706F\u5854\u3001\u7A79\u9876\u5723\u5802\u4E0E\u65C1\u652F\u5B85\u90B8\u51FA\u81EA\u7EF4\u57FA\u7C7B\u9875\u9762\u7684\u641C\u7D22\u6458\u8981\uFF1B\u9875\u9762\u672A\u6293\u53D6\uFF0C\u4E5F\u672A\u4E0E\u5C0F\u8BF4\u5BF9\u7167\u3002"}}],landmarks:{harbor:e(["The Harbour","\u6E2F\u53E3"],["A broad, sheltered harbour of stone quays and wooden piers, filled with merchant cogs and war galleys.","\u5BBD\u9614\u907F\u98CE\u7684\u6E2F\u6E7E\uFF0C\u77F3\u780C\u7801\u5934\u4E0E\u6728\u6808\u6865\u6797\u7ACB\uFF0C\u5546\u8239\u4E0E\u6218\u8230\u4E91\u96C6\u3002"],["The greatest harbour of the west, thick with masts.","\u897F\u5883\u7B2C\u4E00\u5927\u6E2F\uFF0C\u6845\u6A2F\u5982\u6797\u3002"],"high",["agot","acok","twoiaf"],["Lannisport is a large, rich port, the Westerlands' main harbour.","\u5170\u5C3C\u65AF\u6E2F\u662F\u897F\u5883\u7684\u4E3B\u8981\u6E2F\u53E3\uFF0C\u89C4\u6A21\u5B8F\u5927\uFF0C\u5BCC\u5EB6\u7E41\u8363\u3002"],["The number of docks and the harbour's real shape.","\u7801\u5934\u6570\u91CF\u4E0E\u6E2F\u6E7E\u7684\u771F\u5B9E\u5F62\u72B6\u3002"],["A curved basin between two moles with seven piers.","\u4E24\u9053\u9632\u6CE2\u5824\u4E4B\u95F4\u7684\u5F27\u5F62\u6E2F\u6C60\uFF0C\u8BBE\u4E03\u5EA7\u6808\u6865\u3002"]),lighthouse:e(["Lighthouse","\u706F\u5854"],["A tall tower with a gilded cap at the end of the eastern mole, its fire guiding ships in.","\u4E1C\u4FA7\u9632\u6CE2\u5824\u5C3D\u5934\u7684\u91D1\u9876\u9AD8\u5854\uFF0C\u4EE5\u706B\u5149\u4E3A\u6765\u8239\u5F15\u8DEF\u3002"],["A harbour light at the end of the mole; its form is our guess.","\u5824\u7AEF\u7684\u6E2F\u53E3\u706F\u5854\uFF0C\u9020\u578B\u51FA\u81EA\u672C\u573A\u666F\u7684\u63A8\u60F3\u3002"],"low",["awoiaf"],["Wiki-style summaries attribute a large lighthouse to the harbour.","\u7EF4\u57FA\u7C7B\u6458\u8981\u79F0\u6E2F\u53E3\u6709\u4E00\u5EA7\u5927\u578B\u706F\u5854\u3002"],["Whether it exists in the novels, and where.","\u5C0F\u8BF4\u4E2D\u662F\u5426\u5B58\u5728\uFF0C\u4F4D\u4E8E\u4F55\u5904\u3002"],["A tall stone tower with a gold-capped lantern; the form is invented.","\u77F3\u780C\u9AD8\u5854\uFF0C\u91D1\u9876\u706F\u5BA4\uFF1B\u9020\u578B\u4E3A\u865A\u6784\u3002"]),breakwaters:e(["Breakwaters","\u9632\u6CE2\u5824"],["Two curved stone moles shelter the harbour from the Sunset Sea.","\u4E24\u9053\u5F27\u5F62\u77F3\u5824\u4E3A\u6E2F\u6E7E\u6321\u4F4F\u65E5\u843D\u4E4B\u6D77\u7684\u98CE\u6D6A\u3002"],["Two arms of stone enclose the harbour.","\u4E24\u9053\u77F3\u5824\u73AF\u62B1\u6E2F\u6E7E\u3002"],"low",["awoiaf"],["No harbour works are described.","\u4E66\u4E2D\u672A\u63CF\u5199\u4EFB\u4F55\u6E2F\u53E3\u5DE5\u7A0B\u3002"],["Whether a mole system exists and its form.","\u662F\u5426\u6709\u9632\u6CE2\u5824\uFF0C\u53CA\u5176\u5F62\u5236\u3002"],["Two moles with a gap between them; an invented plan.","\u4E24\u9053\u7559\u6709\u7F3A\u53E3\u7684\u77F3\u5824\uFF1B\u5E03\u5C40\u4E3A\u865A\u6784\u3002"]),"lannister-fleet":e(["Lannister Fleet","\u5170\u5C3C\u65AF\u7279\u8230\u961F"],["Crimson-hulled galleys lie among the merchantmen: the western war fleet in port.","\u5546\u8239\u4E4B\u95F4\u6CCA\u7740\u7EA2\u8272\u8239\u8EAB\u7684\u6868\u5E06\u8239\uFF0C\u90A3\u662F\u505C\u6CCA\u5728\u6E2F\u7684\u897F\u5883\u8230\u961F\u3002"],["When Greyjoy's Rebellion began, the ironborn burned the Lannister fleet in this harbour.","\u845B\u96F7\u4E54\u4F0A\u53DB\u4E71\u7206\u53D1\u65F6\uFF0C\u94C1\u6C11\u66FE\u5728\u8FD9\u5EA7\u6E2F\u6E7E\u91CC\u70E7\u6BC1\u5170\u5C3C\u65AF\u7279\u8230\u961F\u3002"],"medium",["agot","acok"],["House Lannister keeps ships at Lannisport; the ironborn burned its fleet at anchor there at the start of Greyjoy's Rebellion.","\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u5728\u5170\u5C3C\u65AF\u6E2F\u9A7B\u6709\u8239\u53EA\uFF1B\u845B\u96F7\u4E54\u4F0A\u53DB\u4E71\u4E4B\u521D\uFF0C\u94C1\u6C11\u5C06\u5176\u505C\u6CCA\u5728\u6E2F\u7684\u8230\u961F\u4ED8\u4E4B\u4E00\u70AC\u3002"],["The fleet's size and composition during the novels.","\u5C0F\u8BF4\u65F6\u671F\u8230\u961F\u7684\u89C4\u6A21\u4E0E\u6784\u6210\u3002"],["Several red-hulled galleys among moored cogs.","\u6570\u8258\u7EA2\u8272\u8239\u8EAB\u7684\u6868\u5E06\u8239\u6DF7\u6CCA\u4E8E\u67EF\u514B\u8239\u4E4B\u95F4\u3002"]),warehouses:e(["Warehouses and Quays","\u8D27\u6808\u4E0E\u7801\u5934"],["Long stone warehouses with red roofs line the quay, with cranes for lifting cargo.","\u7EA2\u9876\u957F\u6761\u77F3\u780C\u8D27\u6808\u6CBF\u7801\u5934\u6392\u5F00\uFF0C\u540A\u673A\u8D77\u5378\u8D27\u7269\u3002"],["The goods of the west are stored behind the quay.","\u897F\u5883\u7684\u8D27\u7269\u56E4\u653E\u5728\u7801\u5934\u540E\u65B9\u3002"],"low",["twoiaf"],["A great trading port implies warehouses and quays; none are described.","\u5927\u578B\u8D38\u6613\u6E2F\u81EA\u7136\u6709\u8D27\u6808\u4E0E\u7801\u5934\uFF0C\u4F46\u4E66\u4E2D\u672A\u4F5C\u63CF\u5199\u3002"],["Actual buildings and layout.","\u5B9E\u9645\u5EFA\u7B51\u4E0E\u5E03\u5C40\u3002"],["Nine warehouses and four cranes along a straight quay.","\u7B14\u76F4\u7801\u5934\u4E0A\u6392\u5E03\u4E5D\u5EA7\u8D27\u6808\u4E0E\u56DB\u53F0\u540A\u673A\u3002"]),"market-square":e(["Market Square","\u96C6\u5E02\u5E7F\u573A"],["An open square of stalls under striped awnings, where western wool, wine and gold change hands.","\u6761\u7EB9\u906E\u7BF7\u4E0B\u644A\u4F4D\u5BC6\u5E03\u7684\u5F00\u9614\u5E7F\u573A\uFF0C\u897F\u5883\u7684\u7F8A\u6BDB\u3001\u7F8E\u9152\u4E0E\u9EC4\u91D1\u5728\u6B64\u4EA4\u6613\u3002"],["The market is the busy heart of the city.","\u96C6\u5E02\u662F\u57CE\u5E02\u7E41\u5FD9\u7684\u5FC3\u810F\u3002"],"low",["twoiaf"],["A rich trading city would have markets; none is described.","\u5BCC\u5EB6\u5546\u57CE\u5FC5\u6709\u96C6\u5E02\uFF0C\u4F46\u4E66\u4E2D\u672A\u4F5C\u63CF\u5199\u3002"],["Location, size and name.","\u4F4D\u7F6E\u3001\u89C4\u6A21\u4E0E\u540D\u79F0\u3002"],["A small square with fourteen stalls and a gilded fountain.","\u5C0F\u5E7F\u573A\uFF0C\u5341\u56DB\u4E2A\u644A\u4F4D\u4E0E\u4E00\u5EA7\u9540\u91D1\u55B7\u6CC9\u3002"]),"lion-street":e(["Lion Street","\u72EE\u5B50\u5927\u9053"],["A broad avenue running straight from the north gate to the harbour, lined with tidy grey houses.","\u81EA\u5317\u95E8\u7B14\u76F4\u901A\u5F80\u6E2F\u53E3\u7684\u5BBD\u9614\u5927\u9053\uFF0C\u4E24\u65C1\u662F\u6574\u6D01\u7684\u7070\u77F3\u6C11\u5C45\u3002"],["Straight streets, grey stone and red roofs: unlike the tangle of King's Landing.","\u8857\u9053\u7B14\u76F4\uFF0C\u7070\u77F3\u7EA2\u74E6\uFF0C\u4E0E\u541B\u4E34\u7684\u6742\u4E71\u8857\u5DF7\u622A\u7136\u4E0D\u540C\u3002"],"low",["twoiaf"],["No street names or plan are known to us.","\u5C31\u6211\u4EEC\u6240\u77E5\uFF0C\u4E66\u4E2D\u6CA1\u6709\u8857\u540D\uFF0C\u4E5F\u6CA1\u6709\u8857\u533A\u5E03\u5C40\u3002"],["The real street plan and names.","\u771F\u5B9E\u7684\u8857\u533A\u5E03\u5C40\u4E0E\u8857\u540D\u3002"],["An invented grid of seven avenues; the name is a placeholder.","\u865A\u6784\u7684\u4E03\u6761\u5927\u9053\u7F51\u683C\uFF1B\u540D\u79F0\u4EC5\u4E3A\u793A\u610F\u3002"]),"great-sept":e(["Great Sept","\u5927\u5723\u5802"],["A grey-stone sept with a great dome and gilded spire on a rise in the west of the city.","\u57CE\u897F\u9AD8\u5730\u4E0A\u7684\u7070\u77F3\u5723\u5802\uFF0C\u5927\u7A79\u9876\u914D\u9540\u91D1\u5C16\u9876\u3002"],["The sept's dome rises above the western rooftops.","\u5723\u5802\u7684\u7A79\u9876\u8038\u7ACB\u5728\u57CE\u897F\u7684\u5C4B\u9876\u4E4B\u4E0A\u3002"],"low",["awoiaf"],["A great sept of Lannisport with a large dome is attributed by wiki summaries.","\u7EF4\u57FA\u6458\u8981\u79F0\u5170\u5C3C\u65AF\u6E2F\u6709\u4E00\u5EA7\u5E26\u5927\u7A79\u9876\u7684\u5723\u5802\u3002"],["Its actual shape and location.","\u771F\u5B9E\u5F62\u72B6\u4E0E\u4F4D\u7F6E\u3002"],["A domed hall with four small towers and coloured windows.","\u7A79\u9876\u5927\u6BBF\uFF0C\u914D\u56DB\u5EA7\u5C0F\u5854\u4E0E\u5F69\u7A97\u3002"]),"cadet-palace":e(["Cadet Palace","\u65C1\u652F\u5B85\u90B8"],["A grand red-roofed palace on a low hill, seat of the Lannisters of Lannisport.","\u4F4E\u4E18\u4E0A\u7684\u7EA2\u9876\u534E\u5B85\uFF0C\u5170\u5C3C\u65AF\u6E2F\u7684\u5170\u5C3C\u65AF\u7279\u65C1\u652F\u5C45\u4E8E\u6B64\u3002"],["A cadet branch of the Lannisters lives in the city below the Rock.","\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7684\u4E00\u652F\u65C1\u7CFB\u4F4F\u5728\u5DE8\u5CA9\u4E0B\u7684\u8FD9\u5EA7\u57CE\u4E2D\u3002"],"low",["affc","awoiaf"],["The Lannisters of Lannisport, a cadet branch, appear in the novels; their residence is not described.","\u201C\u5170\u5C3C\u65AF\u6E2F\u7684\u5170\u5C3C\u65AF\u7279\u201D\u8FD9\u4E00\u65C1\u652F\u89C1\u4E8E\u5C0F\u8BF4\uFF0C\u4F46\u5176\u5B85\u90B8\u672A\u89C1\u63CF\u5199\u3002"],["Whether such a palace exists, its form and site.","\u662F\u5426\u771F\u6709\u8FD9\u6837\u7684\u5B85\u90B8\uFF0C\u53CA\u5176\u5F62\u5236\u4E0E\u4F4D\u7F6E\u3002"],["A palace with four red-capped corner towers and a gilded dome.","\u56DB\u5EA7\u7EA2\u9876\u89D2\u697C\u4E0E\u9540\u91D1\u7A79\u9876\u7684\u5B85\u90B8\u3002"]),"lion-gates":e(["Lion Gates","\u72EE\u95E8"],["Gatehouses on the north, east and west, each flanked by a pair of gilded stone lions.","\u5317\u3001\u4E1C\u3001\u897F\u4E09\u5EA7\u57CE\u95E8\uFF0C\u6BCF\u5EA7\u90FD\u6709\u4E00\u5BF9\u9540\u91D1\u77F3\u72EE\u628A\u5B88\u3002"],["Each gate is guarded by a pair of golden lions.","\u6BCF\u5EA7\u57CE\u95E8\u524D\u90FD\u8E72\u7740\u4E00\u5BF9\u91D1\u72EE\u3002"],"low",["awoiaf"],["Wiki summaries describe main gates each guarded by stone lions.","\u7EF4\u57FA\u6458\u8981\u79F0\u51E0\u5EA7\u4E3B\u57CE\u95E8\u5404\u6709\u77F3\u72EE\u5B88\u536B\u3002"],["Gate names, the lions' look and whether this is canon.","\u57CE\u95E8\u540D\u79F0\u3001\u72EE\u50CF\u6837\u8C8C\uFF0C\u4EE5\u53CA\u662F\u5426\u5C5E\u4E8E\u6B63\u5178\u3002"],["Three gates with six stylised gilded lions built from simple blocks.","\u4E09\u5EA7\u57CE\u95E8\uFF0C\u516D\u5C0A\u4EE5\u7B80\u5355\u51E0\u4F55\u5757\u5851\u6210\u7684\u9540\u91D1\u72EE\u50CF\u3002"]),"city-walls":e(["City Walls","\u57CE\u5899"],["Grey walls with round towers wrap the land side of the city; the harbour side opens onto the quay.","\u7070\u8272\u57CE\u5899\u4E0E\u5706\u5854\u73AF\u62A4\u9646\u4FA7\uFF0C\u4E34\u6E2F\u4E00\u9762\u5411\u7801\u5934\u655E\u5F00\u3002"],["The walls guard the land; the sea is the city's other gate.","\u57CE\u5899\u5B88\u62A4\u9646\u8DEF\uFF0C\u5927\u6D77\u662F\u8FD9\u5EA7\u57CE\u7684\u53E6\u4E00\u9053\u95E8\u3002"],"low",["awoiaf","twoiaf"],["Wiki-level sources describe Lannisport as walled.","\u7EF4\u57FA\u7C7B\u8D44\u6599\u79F0\u5170\u5C3C\u65AF\u6E2F\u6709\u57CE\u5899\u3002"],["Wall height and circuit.","\u57CE\u5899\u9AD8\u5EA6\u4E0E\u8D70\u5411\u3002"],["A roughly hexagonal circuit with round towers.","\u8FD1\u4F3C\u516D\u8FB9\u5F62\u7684\u57CE\u57A3\uFF0C\u914D\u5706\u5854\u3002"]),"casterly-rock-view":e(["Casterly Rock","\u51EF\u5CA9\u57CE"],["To the north, the red-gold bulk of the Rock fills the horizon above the city.","\u5317\u65B9\u5730\u5E73\u7EBF\u4E0A\uFF0C\u51EF\u5CA9\u57CE\u7EA2\u91D1\u8272\u7684\u5E9E\u5927\u5CA9\u4F53\u4FEF\u77B0\u5168\u57CE\u3002"],["The Rock watches over the port from the north; see its own scene.","\u5DE8\u5CA9\u81EA\u5317\u65B9\u5B88\u671B\u6E2F\u53E3\uFF1B\u8BE6\u89C1\u5176\u72EC\u7ACB\u573A\u666F\u3002"],"high",["agot","twoiaf"],["Lannisport lies at the foot of Casterly Rock.","\u5170\u5C3C\u65AF\u6E2F\u4F4D\u4E8E\u51EF\u5CA9\u57CE\u811A\u4E0B\u3002"],["The real distance and direction between them.","\u4E24\u8005\u4E4B\u95F4\u7684\u5B9E\u9645\u8DDD\u79BB\u4E0E\u65B9\u4F4D\u3002"],["A simplified stand-in massif north of the city, not the detailed Rock scene.","\u57CE\u5317\u7684\u7B80\u5316\u5CA9\u4F53\uFF0C\u5E76\u975E\u51EF\u5CA9\u57CE\u7684\u5B8C\u6574\u573A\u666F\u3002"])}};export{c as default};
